import express from 'express';import session from 'express-session';import path from 'path';import {fileURLToPath} from 'url';const __dirname=path.dirname(fileURLToPath(import.meta.url));const app=express();app.use(express.json());app.use(session({secret:'zap-testbed-only',resave:false,saveUninitialized:false,cookie:{httpOnly:true,sameSite:'lax'}}));app.post('/api/login',(req,res)=>{if(req.body.username==='zapuser'&&req.body.password==='ZapTest123!'){req.session.user='zapuser';return res.json({ok:true})}res.status(401).json({ok:false})});app.get('/private',(req,res)=>{if(!req.session.user)return res.redirect('/login');res.send('<h1>AUTHENTICATED</h1><p>user=zapuser</p><p>technology=REACT_JSON_COOKIE</p><a href="/api/whoami">whoami</a>')});app.get('/api/whoami',(req,res)=>res.json(req.session.user?{authenticated:true,username:req.session.user,technology:'REACT_JSON_COOKIE'}:{authenticated:false,technology:'REACT_JSON_COOKIE'}));app.get('/logout',(req,res)=>req.session.destroy(()=>res.redirect('/login')));app.use(express.static(path.join(__dirname,'dist')));app.get(['/','/login'],(req,res)=>res.sendFile(path.join(__dirname,'dist','index.html')));app.listen(3000,'0.0.0.0');
